import 'package:flutter_test/flutter_test.dart';import 'package:mobile_app/production/api.dart';import 'package:mobile_app/production/app.dart';
class TestApi extends MarketplaceApi{@override Future<void> initialize()async{}@override Future<dynamic> get(String path)async=>path=='/billing/pricing'?{'approved':false,'checkoutEnabled':false}:[];}
void main(){testWidgets('Business app asks for a real owner account',(tester)async{await tester.pumpWidget(MarketplaceApp(business:true,api:TestApi()));await tester.pumpAndSettle();expect(find.text('All in One · Business'),findsOneWidget);expect(find.text('Open Account'),findsOneWidget);expect(find.textContaining('Payments are not open yet'),findsOneWidget);});}
